Section Malloc1.
  Context {AMB : Amb} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
  Variable sp0 : word.
  Variables a0s path : list byte.
  Variable envv : list (list byte).
  Variable tid : word.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variable brk : word.
  Variable mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  Variable lim : Z.
  Hypothesis Hva : valid_argv [a0s; path].
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
  Hypothesis ME : main_entry sp0 [a0s; path] envv tid regs0 mem0.
  Hypothesis Hbrk : valid_brk RSEGS brk.

  (* [comment removed for export] *)
(* [comment removed for export] *)
  Definition env_ok (M : word -> option byte) : Prop :=
    O2Open.above_sp0 sp0 mem0 M
    /\ (forall a : word, (0x49770 <= bv_unsigned a < 0x498c8 \/ 0x69aa0 <= bv_unsigned a < 0x69b38)%Z -> ~ (0x4979c <= bv_unsigned a < 0x497a0)%Z -> M a = mem0 a)
       (* [comment removed for export] *)
    /\ (forall a : word, (0x10000 <= bv_unsigned a < 0x38000)%Z \/ (0x384a0 <= bv_unsigned a < 0x384a8)%Z -> M a = None).
      (* [comment removed for export] *)

  (* [comment removed for export] *)
  Hypothesis AL_segs : al_segs = RSEGS.
  Hypothesis AL_rom : al_rom = seg_rom RSEGS.
  Hypothesis AL_malloc : al_malloc_pc = Z_to_bv 64 0x2f94c.
  Hypothesis AL_free : al_free_pc = Z_to_bv 64 0x2f80c.
  Hypothesis AL_tp : al_gp = Z_to_bv 64 0x49840.   (* [comment removed for export] *)
  Hypothesis AL_glob : forall a, al_globals a -> (0x69b38 <= bv_unsigned a < 0x69ee8)%Z.
  Hypothesis AL_grant : forall a, al_grantable a -> (0x1000 <= bv_unsigned a)%Z /\ ~ (0x10000 <= bv_unsigned a < 0x6b000)%Z.
  Hypothesis AL_errno : forall a, al_errno_slot a -> (0x4979c <= bv_unsigned a < 0x497a0)%Z.
  Hypothesis AL_ro : forall a, al_in_ro a -> (bv_unsigned a < 0x6b000)%Z.
  Hypothesis AL_rw : forall a, al_in_rw a -> (bv_unsigned a < 0x6b000)%Z.
  Hypothesis AL_hi : (al_image_hi <= 0x6b000)%Z.
  Hypothesis AL_ret : forall z, In z [0x1766c; 0x17698; 0x17714; 0x17814; 0x17944]%Z -> al_ret_ok (Z_to_bv 64 z).
  Hypothesis AL_env : forall M, env_ok M -> al_env sp0 [a0s; path] envv M.

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).
  Let SPal : (bv_unsigned sp0 mod 16 = 0)%Z := proj2 (proj2 Hvsp).

  Let ENV := O2Open.ENV a0s path.
  Let vm0 := O2Open.vm0 sp0 brk mbase lim.
  Let model1g := O2Open.model1g sp0 tid brk mbase fs0 stdin0 lim.

  (* [comment removed for export] *)
  Definition heap_none (M : word -> option byte) : Prop :=
    forall a : word, (0x6b000 <= bv_unsigned a < bv_unsigned sp0 - 8388608)%Z \/ (0x1000 <= bv_unsigned a < 0x10000)%Z ->
    M a = None.

  (* [comment removed for export] *)
  Lemma mem0_gap_none : heap_none mem0.
Proof.
  unfold heap_none. intros a Ha. pose proof SPlo as Hlo.
  rewrite (main_entry_mem_data sp0 [a0s; path] envv tid regs0 mem0 ME a) by (rewrite stack_max_size_val; lia).
  unfold D_main, D_fd, D_ssp, D_tls, D_tlsB, D_tlsA, D_libc.
  repeat (rewrite MemSplit.wbytes_outside by (rewrite ?length_N_to_le_bytes; cbn [length]; unorm; lia)).
  reflexivity.
Qed.

  (* [comment removed for export] *)
  Lemma mem0_ro_none : forall a : word, (0x10000 <= bv_unsigned a < 0x38000)%Z \/ (0x384a0 <= bv_unsigned a < 0x384a8)%Z -> mem0 a = None.
Proof.
  intros a Ha. pose proof SPlo as Hlo.
  rewrite (main_entry_mem_data sp0 [a0s; path] envv tid regs0 mem0 ME a) by (rewrite stack_max_size_val; lia).
  unfold D_main, D_fd, D_ssp, D_tls, D_tlsB, D_tlsA, D_libc.
  repeat (rewrite MemSplit.wbytes_outside by (rewrite ?length_N_to_le_bytes; cbn [length]; unorm; lia)).
  reflexivity.
Qed.

  Lemma out_win_facts : forall M, O2Open.out_win sp0 mem0 M ->
